constraints:
1 <= n,e <= 10^{5}

expected time complexity: O(e)
expected auxiliary space: O(e)

standard_solution_code:
from collections import defaultdict

class Solution:

	def checkMirrorTree(self, n, e, A, B):
		d = defaultdict(list)
		for i in range(0, 2 * e, 2):
			d[A[i]].append(A[i + 1])
		for i in range(0, 2 * e, 2):
			if B[i] not in d:
				return 0
			elif B[i + 1] != d[B[i]].pop():
				return 0
		return 1
